  out:s=>{const k=s.mdl==='k',keys=k?['1','5','15','61']:['1','2','3','None'],D=k?KN:TD;return T(keys.map(x=>`${k?'KNN, K = '+x.padEnd(4):'Árvore, prof. = '+x.padEnd(4)} treino ${D[x][0].toFixed(3)} | validação ${D[x][1].toFixed(3)}`).join('\n'),'font-size:18px')+pdT(['treino','validação','diferença'],keys.map(x=>[(k?'K = ':'prof. = ')+x,D[x][0].toFixed(3),D[x][1].toFixed(3),(D[x][0]-D[x][1]).toFixed(3)]),{hi:(ri,ci,v)=>ci===2&&+v>.03?HI('am'):''})+cap(k?'K = 1 acerta 100% do treino: decorou. K = 61 olha vizinhos demais: underfitting.':'Profundidade 1 é rasa demais; None decora o treino (100%) sem ganhar na validação.')},
